-- ═══ 0011_role_normalisation.sql ═══
-- Normalise legacy/alias role strings stored in profiles.role and make the
-- RLS helper functions resilient to non-enum values.
--
-- Context: some environments have profiles.role as TEXT (schema drift), which
-- allowed values like 'superadmin' and 'customer'. current_role() returns
-- role_code, so reading such a row threw a cast error and EVERY RLS policy
-- failed for that caller — pages silently rendered empty while privileged
-- service-role writes still succeeded.

-- 1. Data fix: map any non-standard value to a valid role_code.
update public.profiles
set role = (case role::text
  when 'superadmin' then 'super_admin'
  when 'super admin' then 'super_admin'
  when 'administrator' then 'admin'
  when 'customer' then 'agent'
  else 'agent'
end)::role_code
where role::text not in ('super_admin', 'admin', 'agent', 'assistant', 'tech_support', 'finance', 'operations');
-- 2. Hardened helpers: read as text, map known aliases, fall back to 'agent'
-- instead of erroring on unexpected values.
create or replace function public.current_role()
returns role_code language sql stable security definer set search_path = public as $$
  select case (select role::text from public.profiles where id = auth.uid())
    when 'super_admin' then 'super_admin'::role_code
    when 'superadmin' then 'super_admin'::role_code
    when 'admin' then 'admin'::role_code
    when 'administrator' then 'admin'::role_code
    when 'assistant' then 'assistant'::role_code
    when 'tech_support' then 'tech_support'::role_code
    else 'agent'::role_code
  end;
$$;
create or replace function public.is_company_user()
returns boolean language sql stable security definer set search_path = public as $$
  select public.current_role() in ('super_admin', 'admin', 'tech_support');
$$;

-- ═══ 0012_drop_assistants.sql ═══
-- Remove the assistants feature entirely.
--
-- Assistants never get portal access anymore; agents keep their identity
-- rows (agents table) purely for report delivery via email/WhatsApp.
--
-- Note: the 'assistant' role_code enum value is intentionally left in place.
-- Dropping an enum value requires recreating the type, which would cascade
-- into current_role() and every RLS policy that depends on it. No code path
-- can create an assistant anymore, so the value is inert.

-- 1. Remove assistant permission grants and keys.
delete from public.role_permissions where permission like 'assistants.%';
delete from public.permissions where key like 'assistants.%';
-- 2. Leftover assistant profiles lose their role — 'agent' also has no
--    portal access, so this is a safe tombstone rather than a delete that
--    could break FK references (e.g. approved_by).
update public.profiles set role = 'agent' where role::text = 'assistant';
-- 3. Drop the parent-agent linkage column on profiles.
alter table public.profiles drop column if exists parent_agent_id;
-- 4. Drop the assistants table (index, RLS policies drop with it).
drop table if exists public.assistants;
-- 5. Hardened helper: 'assistant' maps to 'agent' — field roles have no
--    portal access and is_company_user() excludes them either way.
create or replace function public.current_role()
returns role_code language sql stable security definer set search_path = public as $$
  select case (select role::text from public.profiles where id = auth.uid())
    when 'super_admin' then 'super_admin'::role_code
    when 'superadmin' then 'super_admin'::role_code
    when 'admin' then 'admin'::role_code
    when 'administrator' then 'admin'::role_code
    when 'tech_support' then 'tech_support'::role_code
    else 'agent'::role_code
  end;
$$;

-- ═══ 0013_communications_log.sql ═══
do $$
begin
  if to_regtype('public.communication_channel') is null then
    create type communication_channel as enum ('sms', 'email', 'whatsapp', 'in_app');
  end if;
end $$;
do $$
begin
  if to_regtype('public.communication_status') is null then
    create type communication_status as enum ('pending', 'sent', 'failed', 'scheduled');
  end if;
end $$;
create table if not exists public.communications (
  id uuid primary key default gen_random_uuid(),
  message text not null,
  channel communication_channel not null,
  status communication_status not null default 'pending',
  recipient_count integer not null default 0,
  recipients text[] default array[]::text[],
  sent_by uuid references public.profiles(id) on delete set null,
  sent_at timestamptz,
  scheduled_for timestamptz,
  error_message text,
  metadata jsonb default '{}'::jsonb,
  created_at timestamptz not null default now()
);
-- Indexes for common queries
create index if not exists idx_communications_sent_by on public.communications(sent_by);
create index if not exists idx_communications_channel on public.communications(channel);
create index if not exists idx_communications_status on public.communications(status);
create index if not exists idx_communications_sent_at on public.communications(sent_at desc);
create index if not exists idx_communications_scheduled_for on public.communications(scheduled_for) where status = 'scheduled';
-- RLS: Only company staff can view communications
alter table public.communications enable row level security;
drop policy if exists "Company staff can view all communications" on public.communications;


create policy "Company staff can view all communications"
  on public.communications for select
  using (
    exists (
      select 1 from public.profiles
      where id = auth.uid()
      and role in ('super_admin', 'admin', 'tech_support')
    )
  );
drop policy if exists "Company staff can insert communications" on public.communications;


create policy "Company staff can insert communications"
  on public.communications for insert
  with check (
    exists (
      select 1 from public.profiles
      where id = auth.uid()
      and role in ('super_admin', 'admin', 'tech_support')
    )
  );
-- Service role bypasses RLS for automated updates;

-- ═══ 0014_finance_operations_roles.sql ═══
-- 0014_finance_operations_roles.sql
-- The app code and staff-management UI already grant dashboard access to the
-- "finance" and "operations" company roles, but the role_code enum rejected
-- them, so profiles for these roles could never be created.

alter type public.role_code add value if not exists 'finance';
commit;
begin;
alter type public.role_code add value if not exists 'operations';
commit;
begin;
-- Extend the company-role gate so existing RLS policies cover the new roles.
create or replace function public.is_company_user()
returns boolean language sql stable security definer set search_path = public as $$
  select coalesce(
    (select role::text in ('super_admin','admin','tech_support','finance','operations') from public.profiles where id = auth.uid()),
    false
  );
$$;

-- ═══ 0015_staff_role_helpers.sql ═══
-- Apply after 0014 has committed its enum additions. Do not rewrite account
-- roles or trust auth.users.raw_user_meta_data to grant staff privileges.
create or replace function public.current_role()
returns public.role_code language sql stable security definer set search_path = public as $$
  select case lower(trim((select role::text from public.profiles where id = auth.uid() and status::text = 'active')))
    when 'super_admin' then 'super_admin'::public.role_code
    when 'superadmin' then 'super_admin'::public.role_code
    when 'super admin' then 'super_admin'::public.role_code
    when 'admin' then 'admin'::public.role_code
    when 'administrator' then 'admin'::public.role_code
    when 'tech_support' then 'tech_support'::public.role_code
    when 'finance' then 'finance'::public.role_code
    when 'operations' then 'operations'::public.role_code
    when 'assistant' then 'assistant'::public.role_code
    else 'agent'::public.role_code
  end;
$$;
create or replace function public.is_company_user()
returns boolean language sql stable security definer set search_path = public as $$
  select coalesce(
    (select status::text = 'active' from public.profiles where id = auth.uid())
    and public.current_role() in ('super_admin','admin','tech_support','finance','operations'),
    false
  );
$$;

-- ═══ 0016_restore_missing_access_policies.sql ═══
-- Restore missing baseline access policies without replacing existing policies.
-- Hosted deployments created outside the migration runner may have RLS enabled
-- but no staff/profile policies, causing valid logins to appear profile-less.
-- This migration does not disable RLS or alter account roles/passwords.

do $restore_policy$
begin
  if not exists (
    select 1 from pg_policies
    where schemaname = 'public' and tablename = 'profiles' and policyname = 'profiles_select_self'
  ) then
    create policy "profiles_select_self"  on public.profiles for select using (id = auth.uid() or public.is_company_user());
  end if;
end
$restore_policy$;
do $restore_policy$
begin
  if not exists (
    select 1 from pg_policies
    where schemaname = 'public' and tablename = 'profiles' and policyname = 'profiles_update_self'
  ) then
    create policy "profiles_update_self"  on public.profiles for update using (id = auth.uid()) with check (id = auth.uid() and role = public.current_role() and agent_id = public.current_agent_id());
  end if;
end
$restore_policy$;
do $restore_policy$
begin
  if not exists (
    select 1 from pg_policies
    where schemaname = 'public' and tablename = 'profiles' and policyname = 'profiles_admin_write'
  ) then
    create policy "profiles_admin_write"  on public.profiles for all using (public.current_role() = 'super_admin') with check (public.current_role() = 'super_admin');
  end if;
end
